StructuralRule.Predicate:
FunctionCall: 
    possibleTargets contains [Function:
        name matches "(add|insert)Subview:_:.*"
        and enclosingClass.supers contains [Class: name == "UIKit.UIView"]
    ]
    and arguments[0] is [VariableAccess va: 
        variable.name matches "PUT_REGEX_HERE" 
        and variable.type.definition.supers contains [Class: name == "UIKit.UITextInput"]
        and not enclosingFunction contains [FunctionCall: possibleTargets contains [Function:
                name == "isSecureTextEntry:_:" 
                and enclosingClass.supers contains [Class: name == "UIKit.UITextInput"]
              ] 
              and instance is [VariableAccess: variable is [Variable: name == va.variable.name]*]
              and arguments[0] is [BooleanLiteral: value is true]
        ] 
        and not enclosingFunction contains [FunctionCall: possibleTargets contains [Function:
                name == "autocorrectionType:_:" 
                and enclosingClass.supers contains [Class: name == "UIKit.UITextInput"]
              ] 
              and instance is [VariableAccess: variable is [Variable: name == va.variable.name]*]
              and arguments[0] is [FunctionCall:  possibleTargets contains [Function:
                    /* Enum UITextAutocorrectionType.no */
                    enclosingClass is [Class: 
                        supers contains [Class: name == "UIKit.UITextAutocorrectionType"]
                    ] 
                    and name == "no~make" 
                 ]
              ]
        ] 
        and not enclosingFunction contains [FunctionCall: possibleTargets contains [Function:
                name == "isHidden:_:"
              ] 
              and instance is [VariableAccess: variable is [Variable: name == va.variable.name]*]
              and arguments[0] is [BooleanLiteral: value is true]
        ] 
    ]

