FunctionCall:
    possibleTargets contains [Function:
        name == "url:scheme:user:password:host:port:path:query:fragment:"
        and enclosingClass.supers contains [Class:
            name == "_StringProcessing.RegexComponente"
        ]
    ]
    and arguments[2] is [FunctionCall:
        possibleTargets contains [Function:
            name == "defaultValue~make"
            and enclosingClass.supers contains [Class:
                name == "Foundation.URL.ParseStrategy.ComponentParseStrategy"
            ]
        ]
        and arguments[0] is [Expression:
            constantValue == ""
        ]*
    ]

FunctionCall:
    possibleTargets contains [Function:
        name == "url:scheme:user:password:host:port:path:query:fragment:"
        and enclosingClass.supers contains [Class:
            name == "_StringProcessing.RegexComponent"
        ]
    ]
    and arguments[2] is [FunctionCall:
        possibleTargets contains [Function:
            name == "defaultValue~make"
            and enclosingClass.supers contains [Class:
                name == "Foundation.URL.ParseStrategy.ComponentParseStrategy"
            ]
        ]
        and arguments[0] is [Expression:
            not constantValue.null
            and not constantValue is [Null:]
            and not constantValue != ""
        ]*
    ]

FunctionCall:
    possibleTargets contains [Function:
        ( name == "setNavigationDelegate:_:"
          or name == "navigationDelegate:_:")
        and enclosingClass.supers contains [Class:
            name == "WebKit.WKWebView"
        ]
    ]
    and (
        /* Delegate is nil */
        (arguments[0].constantValue is [Null:] or arguments[0].constantValue == 0)
        /* Delegate does not properly validate links */
        or arguments[0] is [Expression delegate:
            /* According to bug 57776 comment #13, reachingTypes/possibleTypes may not include static type, so checking both */
            not reachingTypes contains [Type: definition.supers contains [Class: labels contains "WKNavigationDelegate_LinkValidation"]]
            and not type is [Type: definition.supers contains [Class: labels contains "WKNavigationDelegate_LinkValidation"]]
        ]
    )
    and not enclosingFunction reachedBy [Function:
        name == "viewDidDisappear:_:"
        or name == "viewWillDisappear:_:"
        or name == "viewDidUnload"
    ]

FunctionCall:
    possibleTargets contains [Function:
        name matches "(add|insert)Subview:_:.*"
        and enclosingClass.supers contains [Class: name == "UIKit.UIView"]
    ]
    and (
        instance is [FunctionCall:
            possibleTargets contains [Function:
                name == "window"
                and enclosingClass.labels contains "UIApplicationDelegate"
            ]
        ]
        or instance is [VariableAccess:
            type.name == "UIKit.UIWindow"
        ]
    )
    and enclosingFunction is [Function:
        name matches "applicationDidEnterBackground:_:|applicationWillResignActive:_:"
        and enclosingClass.labels contains "UIApplicationDelegate"
    ]

FunctionCall:
    possibleTargets contains [Function:
        ( name == "setDelegate:_:"
          or name == "delegate:_:")
        and enclosingClass.supers contains [Class:
            name == "UIKit.UIWebView"
        ]
    ]
    and (
        /* Delegate is nil */
        (arguments[0].constantValue is [Null:] or arguments[0].constantValue == 0)
        /* Delegate does not properly validate links */
        or arguments[0] is [Expression delegate:
            /* According to bug 57776 comment #13, reachingTypes/possibleTypes may not include static type, so checking both */
            not reachingTypes contains [Type: definition.supers contains [Class: labels contains "UIWebViewDelegate_LinkValidation"]]
            and not type is [Type: definition.supers contains [Class: labels contains "UIWebViewDelegate_LinkValidation"]]
        ]
    )
    and not enclosingFunction reachedBy [Function:
        name == "viewDidDisappear:_:"
        or name == "viewWillDisappear:_:"
        or name == "viewDidUnload"
    ]

Class:
    /* Application Delegate */
    labels contains "UIApplicationDelegate"
    /* ... which contains a handler for custom URL IPC */
    and functions contains [Function:
        name == "application:_:handleOpen:"
        or name == "application:_:open:sourceApplication:annotation:"
        or name == "application:_:open:options:"
    ]*
    /* ... and it either does not implement any of the callbacks where validation can stop the application launching */
    and (not functions contains [Function:
        /* When checking that a function does not exist, need to check for swift 2 and swift 3 signatures */
        name == "application:_:willFinishLaunchingWithOptions:"
        or name == "application:willFinishLaunchingWithOptions"
        or name == "application:_:didFinishLaunchingWithOptions:"
        or name == "application:didFinishLaunchingWithOptions"
    ]
    /* ... or it implements it but they do not access the URL used to call the app or does not return false */
    or functions contains [Function f:
        (name == "application:_:willFinishLaunchingWithOptions:"
        or name == "application:_:didFinishLaunchingWithOptions:")
        and (
            not contains [FunctionCall:
                possibleTargets contains [Function:
                    name == "url"
                    and enclosingClass.supers contains [Class:
                        name == "UIKit.UIApplicationLaunchOptionsKey"
                    ]
                ]
            ]
            or not contains [ReturnStatement:
                /* see bug 57773 */
                expression.constantValues contains [Boolean: is false]
                or expression contains [VariableAccess:
                    variable is [Variable:
                        uses contains [VariableAccess va:
                            enclosingStatement is [AssignmentStatement:
                                lhs is [VariableAccess va2: va2 is va]
                                and rhs.constantValues contains [Boolean: is false]
                            ]
                        ]
                    ]
                ]
            ]
        )
    ]*)

Class:
    /* Application Delegate */
    labels contains "UIApplicationDelegate"
    /* ... which contains a handler for custom URL IPC */
    and functions contains [Function:
        name == "application:_:handleOpen:"
        or name == "application:_:open:sourceApplication:annotation:"
        or name == "application:_:open:options:"
    ]*

Class:
    /* AppDelegate */
    labels contains "UIApplicationDelegate"
    /* ... and it implements it but it does not check or does not return false */
    and functions contains [Function f:
        name == "application:_:shouldAllowExtensionPointIdentifier:"
        and (
            not contains [FunctionCall:
                possibleTargets contains [Function:
                    name == "keyboard"
                    and enclosingClass.supers contains [Class:
                        name == "UIKit.UIApplicationExtensionPointIdentifier"
                        or name == "UIKit.UIApplication.ExtensionPointIdentifier"
                    ]
                ]
            ]
            and not contains [FieldAccess:
                field.name == "keyboard"
                and field.enclosingClass.supers contains [Class:
                    name == "UIKit.UIApplication.ExtensionPointIdentifier"
                ]
            ]
            or not contains [ReturnStatement:
                /* see bug 57773 */
                expression.constantValues contains [Boolean: is false]
                or expression contains [VariableAccess:
                    variable is [Variable:
                        uses contains [VariableAccess va:
                            enclosingStatement is [AssignmentStatement:
                                lhs is [VariableAccess va2: va2 is va]
                                and rhs.constantValues contains [Boolean: is false]
                            ]
                        ]
                    ]
                ]
            ]
        )
    ]*

Class:
    /* AppDelegate */
    labels contains "UIApplicationDelegate"
    /* ... and it either does not implement shouldAllowExtensionPointIdentifier callback */
    and not functions contains [Function:
        /* When checking that a function does not exist, need to check for swift 2 and swift 3 signatures */
        name == "application:_:shouldAllowExtensionPointIdentifier:"
        or name == "application:shouldAllowExtensionPointIdentifier"
    ]

Class:
    /* SLComposeServiceViewController */
    supers contains [Class:
        name == "Social.SLComposeServiceViewController"
    ]
    /* ... and it either does not implement isContentValid callback */
    and (not functions contains [Function:
        name == "isContentValid"
    ]
    /* ... or it implements it but it does not return false */
     or functions contains [Function f:
         name == "isContentValid"
         and not contains [ReturnStatement:
            /* see bug 57773 */
            expression.constantValues contains [Boolean: is false]
            or expression contains [VariableAccess:
                variable is [Variable:
                    uses contains [VariableAccess va:
                        enclosingStatement is [AssignmentStatement:
                            lhs is [VariableAccess va2: va2 is va]
                            and rhs.constantValues contains [Boolean: is false]
                        ]
                    ]
                ]
            ]
         ]
    ]*)

FunctionCall:
    possibleTargets contains [Function:
        (name == "init^:properties:" or constructor)
        and enclosingClass.supers contains [Class: name == "Foundation.HTTPCookie"]
    ]
    and arguments[0] is [VariableAccess:
        variable is [Variable props1:
            /* Not configured */
            not enclosingFunction contains [FunctionCall:
                (possibleTargets contains [Function:
                    name == "assign:_:_:"
                    and enclosingClass.supers contains [Class: name == "Swift.Dictionary"]
                ]
                and instance is [VariableAccess: variable is props1]
                and arguments[0] is [FunctionCall:
                    possibleTargets contains [Function:
                        name == "secure"
                        and enclosingClass.supers contains [Class:
                            name == "Foundation.HTTPCookiePropertyKey"
                        ]
                    ]
                ]
                and arguments[1] is [BooleanLiteral: value is true])
                or (possibleTargets contains [Function:
                    name matches "set(Object|Value):_:forKey:"
                    and enclosingClass.supers contains [Class:
                        name == "Foundation.NSDictionary"
                        or name == "Foundation.Dictionary"
                    ]
                ]
                and instance is [VariableAccess: variable is props1]
                and arguments[1] is [FunctionCall:
                    possibleTargets contains [Function:
                        name == "secure"
                        and enclosingClass.supers contains [Class:
                            name == "Foundation.HTTPCookiePropertyKey"
                        ]
                    ]
                ]
                and arguments[0] is [BooleanLiteral: value is true])
            ]
            /* Incorrect configuration */
            or enclosingFunction contains [FunctionCall:
                (possibleTargets contains [Function:
                    name == "assign:_:_:"
                    and enclosingClass.supers contains [Class: name == "Swift.Dictionary"]
                ]
                and instance is [VariableAccess: variable is props1]
                and arguments[0] is [FunctionCall:
                    possibleTargets contains [Function:
                        name == "secure"
                        and enclosingClass.supers contains [Class:
                            name == "Foundation.HTTPCookiePropertyKey"
                        ]
                    ]
                ]
                and arguments[1] is [BooleanLiteral: value is false])
                or (possibleTargets contains [Function:
                    name matches "set(Object|Value):_:forKey:"
                    and enclosingClass.supers contains [Class:
                        name == "Foundation.NSDictionary"
                        or name == "Foundation.Dictionary"
                    ]
                ]
                and instance is [VariableAccess: variable is props1]
                and arguments[1] is [FunctionCall:
                    possibleTargets contains [Function:
                        name == "secure"
                        and enclosingClass.supers contains [Class:
                            name == "Foundation.HTTPCookiePropertyKey"
                        ]
                    ]
                ]
                and arguments[0] is [BooleanLiteral: value is false])
            ]
        ]*
    ]

FunctionCall:
    possibleTargets contains [Function:
        name matches "init\^:request:delegate:(startImmediately:)?"
        and enclosingClass.supers contains [Class:
            name == "Foundation.NSURLConnection"
        ]
    ]
    and arguments[0] is [Expression request:]
    and (
        /* Delegate is nil */
        (arguments[1].constantValue is [Null:] or arguments[1].constantValue == 0)
        /* Delegate does cache responses */
        or arguments[1] is [Expression delegate:
            /* According to bug 57776 comment #13, reachingTypes/possibleTypes may not include static type, so checking both */
            not reachingTypes contains [Type: definition.supers contains [Class: labels contains "NSURLConnectionDataDelegate_NoCache"]]
            and not type is [Type: definition.supers contains [Class: labels contains "NSURLConnectionDataDelegate_NoCache"]]
        ]
    )

FunctionCall:
    possibleTargets contains [Function:
        name == "assign:_:_:"
    ]
    and arguments[0] is [VariableAccess:
        variable.name == "NSPersistentStoreFileProtectionKey"
    ]
    and arguments[1] is [FunctionCall fc:
        possibleTargets contains [Function:
            name == "none"
        ]
    ]

FunctionCall:
    possibleTargets contains [Function:
        name == "assign:_:_:"
    ]
    and arguments[0] is [VariableAccess:
        variable.name == "NSPersistentStoreFileProtectionKey"
    ]
    and arguments[1] is [FunctionCall fc:
        possibleTargets contains [Function:
            (name == "completeUnlessOpen"
            or name == "completeUntilFirstUserAuthentication")
        ]
    ]

FunctionCall:
    possibleTargets contains [Function:
        (name == "init^:user:password:persistence:"
        or name == "init^:identity:certificates:persistence:")
        and enclosingClass.supers contains [Class:
            name == "Foundation.URLCredential"
        ]
    ]
    and arguments[2] is [FunctionCall:
        possibleTargets contains [Function:
            name == "synchronizable"
        ]
    ]

FunctionCall fc:
    possibleTargets contains [Function:
        name == "SecTrustEvaluate:_:_:"
    ]
    and (
        /* Return value is assigned to a variable that is only accessed one (the assignment), so not checked */
        in [AssignmentStatement:
            rhs is fc
            and lhs is [VariableAccess:
                variable.uses.length < 2
            ]
        ]
        /* or arg1 is not checked */
        or fc.arguments[1] is [VariableAccess:
            variable.uses.length < 3
        ]
    )

FunctionCall fc:
    possibleTargets contains [Function:
        name == "archiveRootObject:_:toFile:"
        and enclosingClass.supers contains [Class: name == "Foundation.NSKeyedArchiver"]
    ]
    and enclosingFunction is [Function fileAccessFunction:
        not fileAccessFunction contains [FunctionCall:
            function.name == "setAttributes:_:ofItemAtPath:"
            and function.enclosingClass.supers contains [Class: name == "Foundation.FileManager"]
            and (arguments[1] is [VariableAccess:
                variable is [Variable file1:
                    fc.arguments[1] is [VariableAccess:
                        variable is file1
                    ]
                ]
            ] or arguments[1] is [FunctionCall file2:
                fc.arguments[1] is [FunctionCall:
                    function.name == file2.name
                ]
            ]
            or (arguments[1].constantValue == fc.arguments[1].constantValue
                and not arguments[1].constantValue is [Null:]
                and not arguments[1].constantValue.null)
            )
        ]
        and not fileAccessFunction contains [FunctionCall:
            function.name == "createFile:atPath:contents:attributes:"
            and function.enclosingClass.supers contains [Class: name == "Foundation.FileManager"]
            and (arguments[0] is [VariableAccess:
                variable is [Variable file3:
                    fc.arguments[1] is [VariableAccess:
                        variable is file3
                    ]
                ]
            ] or arguments[1] is [FunctionCall file4:
                fc.arguments[1] is [FunctionCall:
                    function.name == file4.name
                ]
            ]
            or (arguments[1].constantValue == fc.arguments[1].constantValue
                and not arguments[1].constantValue is [Null:]
                and not arguments[1].constantValue.null)
            )
        ]
    ]

FunctionCall fc:
    possibleTargets contains [Function:
        name == "archiveRootObject:_:toFile:"
        and enclosingClass.supers contains [Class: name == "Foundation.NSKeyedArchiver"]
    ]
    and enclosingFunction is [Function fileAccessFunction:
        not fileAccessFunction contains [FunctionCall:
            function.name == "setAttributes:_:ofItemAtPath:"
            and function.enclosingClass.supers contains [Class: name == "Foundation.FileManager"]
            and (arguments[1] is [VariableAccess:
                variable is [Variable file1:
                    fc.arguments[1] is [VariableAccess:
                        variable is file1
                    ]
                ]
            ] or arguments[1] is [FunctionCall file2:
                fc.arguments[1] is [FunctionCall:
                    function.name == file2.name
                ]
            ]
            or (arguments[1].constantValue == fc.arguments[1].constantValue
                and not arguments[1].constantValue is [Null:]
                and not arguments[1].constantValue.null)
            )
        ]
        and not fileAccessFunction contains [FunctionCall:
            function.name == "createFile:atPath:contents:attributes:"
            and function.enclosingClass.supers contains [Class: name == "Foundation.FileManager"]
            and (arguments[0] is [VariableAccess:
                variable is [Variable file3:
                    fc.arguments[1] is [VariableAccess:
                        variable is file3
                    ]
                ]
            ] or arguments[1] is [FunctionCall file4:
                fc.arguments[1] is [FunctionCall:
                    function.name == file4.name
                ]
            ]
            or (arguments[1].constantValue == fc.arguments[1].constantValue
                and not arguments[1].constantValue is [Null:]
                and not arguments[1].constantValue.null)
            )
        ]
    ]

FunctionCall fc:
    /* functions that take no options/attributes argument */
    possibleTargets contains [Function:
        (name matches "write:to(File)?:atomically:"
        and enclosingClass.supers contains [Class:
            name matches "Foundation\.NS(Array|Data|Dictionary)"
        ])
        or (name matches "write:to(File)?:atomically:encoding:"
        and enclosingClass.supers contains [Class:
            name matches "(Foundation|Swift)\.(NS)?String(Protocol)?"
        ])
        or (name == "init^:toFileAtPath:append:"
        and enclosingClass.supers contains [Class: name == "Foundation.OutputStream"])
        or (name == "init^:url:append:"
        and enclosingClass.supers contains [Class: name == "Foundation.OutputStream"])
    ]
    /* .. but file has been configured using setAttributes */
    and (enclosingFunction is [Function fileAccessFunction:
        not fileAccessFunction contains [FunctionCall:
            possibleTargets contains [Function:
                name == "setAttributes:ofItemAtPath:"
                and enclosingClass.supers contains [Class: name == "Foundation.FileManager"]
            ]
            and (arguments[1] is [VariableAccess:
                variable is [Variable file1:
                    fc.arguments[0] is [VariableAccess:
                        variable is file1
